91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	    }
