126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        validateRequiredFields(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
133	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
134	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
135	        rejectDuplicateTelephone(telephone);
136	        owner.setTelephone(telephone);
137	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
138	        if (owner.getRegistrationDate() == null) {
139	            owner.setRegistrationDate(LocalDate.now());
140	        }
141	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
