149	    /**
150	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
151	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
152	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
153	     *
154	     * @param lastName the owner's last name
155	     * @return the assigned customer code
156	     */
157	    private String nextCustomerCode(String lastName) {
158	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
159	        int sequence = this.clinicService.findAllOwners().size() + 1;
160	        return String.format("%s-%04d", last3, sequence);
161	    }
162	
163	    /**
164	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
165	     * offending field so the client learns about all of them at once.
166	     *
167	     * @param ownerFieldsDto the submitted owner fields
168	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
169	     *                                     missing or blank
170	     */
171	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
172	        List<String> errors = new ArrayList<>();
173	        if (isBlank(ownerFieldsDto.getFirstName())) {
174	            errors.add("firstName");
175	        }
176	        if (isBlank(ownerFieldsDto.getLastName())) {
177	            errors.add("lastName");
178	        }
179	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
180	            errors.add("address");
181	        }
182	        if (isBlank(ownerFieldsDto.getCity())) {
183	            errors.add("city");
184	        }
185	        if (isBlank(ownerFieldsDto.getTelephone())) {
186	            errors.add("telephone");
187	        }
188	        if (!errors.isEmpty()) {
189	            throw new MissingOwnerFieldsException(errors);
190	        }
191	    }
192	
193	    private boolean isBlank(String value) {
194	        return value == null || value.isBlank();
195	    }
196	
197	    /**
198	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
199	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
200	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
201	     * followed by 8 to 15 digits.
202	     *
203	     * @param telephone the raw telephone value as submitted
204	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
205	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
206	     */
207	    private String normalizeTelephone(String telephone) {
208	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
209	        String nationalSignificantNumber;
210	        if (cleaned.startsWith("+")) {
211	            nationalSignificantNumber = cleaned.substring(1);
212	        } else {
213	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
214	            nationalSignificantNumber = "61" + national;
215	        }
216	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
217	            throw new InvalidTelephoneException(telephone);
218	        }
219	        return "+" + nationalSignificantNumber;
220	    }
221	
222	    /**
223	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
224	     * value is treated as absent and returns {@code null}); when present the value must be a
225	     * syntactically valid address, and is stored and returned lower-cased.
226	     *
227	     * @param email the raw email value as submitted, may be {@code null}
228	     * @return the lower-cased email, or {@code null} when none was supplied
229	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
230	     */
231	    private String normalizeEmail(String email) {
232	        if (email == null || email.isBlank()) {
233	            return null;
234	        }
235	        String normalized = email.trim().toLowerCase();
236	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
237	            throw new InvalidEmailException(email);
238	        }
239	        return normalized;
240	    }
241	
242	    /**
243	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
244	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
245	     * comparison, so numbers that differ only in formatting still count as duplicates.
246	     *
247	     * @param e164Telephone the E.164 telephone of the owner being created
248	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
249	     */
250	    private void rejectDuplicateTelephone(String e164Telephone) {
251	        boolean inUse = this.clinicService.findAllOwners().stream()
252	            .map(Owner::getTelephone)
253	            .filter(existing -> existing != null)
254	            .map(this::toComparableTelephone)
255	            .filter(existing -> existing != null)
256	            .anyMatch(e164Telephone::equals);
257	        if (inUse) {
258	            throw new DuplicateTelephoneException(e164Telephone);
259	        }
260	    }
261	
262	    /**
263	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
264	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
265	     * than aborting the whole create.
266	     */
267	    private String toComparableTelephone(String telephone) {
268	        try {
269	            return normalizeTelephone(telephone);
270	        } catch (InvalidTelephoneException ex) {
271	            return null;
272	        }
273	    }
274	
275	    /**
276	     * Applies the household rule to an owner being created. An owner belongs to the same household
277	     * as an existing owner when their lastName and address both match (compared case-insensitively
278	     * with runs of whitespace collapsed to a single space).
279	     *
280	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
281	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
282	     * does, the new owner and every existing owner in the household are assigned the same stable
283	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
284	     *
285	     * @param owner            the owner being created
286	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
287	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
288	     *                                     the request did not opt in with {@code sharesHousehold=true}
289	     */
290	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
291	        String lastNameKey = toHouseholdKey(owner.getLastName());
292	        String addressKey = toHouseholdKey(owner.getAddress());
293	        List<Owner> household = this.clinicService.findAllOwners().stream()
294	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
295	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
296	            .toList();
297	        if (household.isEmpty()) {
298	            return;
299	        }
300	        if (!Boolean.TRUE.equals(sharesHousehold)) {
301	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
302	        }
303	        String householdId = householdId(lastNameKey, addressKey);
304	        owner.setHouseholdId(householdId);
305	        for (Owner existing : household) {
306	            if (!householdId.equals(existing.getHouseholdId())) {
307	                existing.setHouseholdId(householdId);
308	                this.clinicService.saveOwner(existing);
309	            }
310	        }
311	    }
312	
313	    /**
314	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
315	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
316	     * lastName and address keys. Being a pure function of the household, every owner in it derives
317	     * the same value regardless of creation order.
318	     *
319	     * @param lastNameKey the normalized household lastName key
320	     * @param addressKey  the normalized household address key
321	     * @return the household identifier
322	     */
323	    private String householdId(String lastNameKey, String addressKey) {
324	        try {
325	            byte[] digest = MessageDigest.getInstance("SHA-256")
326	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
327	            StringBuilder hex = new StringBuilder(digest.length * 2);
328	            for (byte b : digest) {
329	                hex.append(String.format("%02x", b));
330	            }
331	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
332	        } catch (NoSuchAlgorithmException ex) {
333	            throw new IllegalStateException("SHA-256 not available", ex);
334	        }
335	    }
336	
337	    /**
338	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
339	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
340	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
341	     * string.
342	     */
343	    private String toHouseholdKey(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
352	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
353	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
354	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
355	     * value, or one that is blank once trimmed, normalizes to an empty string.
356	     *
357	     * @param address the raw address value as submitted, may be {@code null}
358	     * @return the normalized address, or an empty string when none was supplied
359	     */
360	    private String normalizeAddress(String address) {
361	        if (address == null) {
362	            return "";
363	        }
364	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
365	        if (collapsed.isEmpty()) {
366	            return "";
367	        }
368	        String[] tokens = collapsed.split(" ");
369	        StringBuilder normalized = new StringBuilder(collapsed.length());
370	        for (int i = 0; i < tokens.length; i++) {
371	            if (i > 0) {
372	                normalized.append(' ');
373	            }
374	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
375	        }
376	        return normalized.toString();
377	    }
378	
