389	        currentOwner.setLastName(ownerFieldsDto.getLastName());
390	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
391	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
392	        this.clinicService.saveOwner(currentOwner);
