460	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
461	    @Override
462	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
463	        Owner owner = this.clinicService.findOwnerById(ownerId);
464	        if (owner != null) {
465	            Pet pet = owner.getPet(petId);
466	            if (pet != null) {
467	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
468	            }
469	        }
470	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
471	    }
472	}
